using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<vector<int>> adj(N + 1);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> bpar(N + 1, 0), ypar(N + 1, 0);

    // Blue DFS from 1
    vector<bool> vis(N + 1, false);
    auto dfs_blue = [&](auto& self, int u) -> void {
        vis[u] = true;
        for (int v : adj[u]) {
            if (!vis[v]) {
                bpar[v] = u;
                self(self, v);
            }
        }
    };
    dfs_blue(dfs_blue, 1);

    // Yellow DFS from 2, avoiding bpar
    fill(vis.begin(), vis.end(), false);
    auto dfs_yellow = [&](auto& self, int u) -> void {
        vis[u] = true;
        for (int v : adj[u]) {
            if (!vis[v] && bpar[v] != u) {
                ypar[v] = u;
                self(self, v);
            }
        }
    };
    dfs_yellow(dfs_yellow, 2);

    for (int i = 1; i <= N; ++i) {
        if (i != 1 && bpar[i] == 0) {
            cout << "No\n";
            return 0;
        }
        if (i != 2 && ypar[i] == 0) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    cout << ypar[1] << "\n";
    cout << bpar[2] << "\n";
    for (int i = 3; i <= N; ++i) {
        cout << bpar[i] << " " << ypar[i] << "\n";
    }
    return 0;
}

