using namespace std;

const int MOD = 998244353;

struct HashTable {
    static const int SIZE = 1 << 16;
    static const int MASK = SIZE - 1;
    uint32_t keys[SIZE];
    int vals[SIZE];
    int head[SIZE];
    int nxt[SIZE];
    int sz;

    void clear() {
        fill(head, head + SIZE, -1);
        sz = 0;
    }

    void add(uint32_t k, int v) {
        int h = (k * 2654435761u) & MASK;
        for (int e = head[h]; e != -1; e = nxt[e]) {
            if (keys[e] == k) {
                vals[e] = (vals[e] + v) % MOD;
                return;
            }
        }
        keys[sz] = k;
        vals[sz] = v;
        nxt[sz] = head[h];
        head[h] = sz++;
    }
};

HashTable ht_cur, ht_nxt;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    if (!(cin >> H >> W)) return 0;
    vector<string> grid(H);
    for (int i = 0; i < H; ++i) cin >> grid[i];

    if (W > H) {
        vector<string> transposed(W, string(H, ' '));
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                transposed[j][i] = grid[i][j];
            }
        }
        grid = transposed;
        swap(H, W);
    }

    ht_cur.clear();
    ht_cur.add(0, 1);

    int shift = 2 * (W - 1);

    for (int r = 0; r < H; ++r) {
        for (int c = 0; c < W; ++c) {
            ht_nxt.clear();
            char ch = grid[r][c];

            for (int i = 0; i < ht_cur.sz; ++i) {
                uint32_t m = ht_cur.keys[i];
                int ways = ht_cur.vals[i];

                int top = (m & 3);
                int left = ((m >> shift) & 3);

                for (int val = 0; val < 3; ++val) {
                    if (ch != '?' && ch - '1' != val) continue;
                    if (r > 0 && val == top) continue;
                    if (c > 0 && val == left) continue;

                    uint32_t nm = (m >> 2) | ((uint32_t)val << shift);
                    ht_nxt.add(nm, ways);
                }
            }
            ht_cur = ht_nxt;
        }
    }

    int ans = 0;
    for (int i = 0; i < ht_cur.sz; ++i) {
        ans = (ans + ht_cur.vals[i]) % MOD;
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
