long long count_occurrences(long long N, const string& S) {
    if (N <= 0) return 0;
    string N_str = to_string(N);
    int L_N = N_str.size();
    int M = S.size();

    long long total = 0;

    auto p10 = [](int p) -> long long {
        long long res = 1;
        for (int i = 0; i < p; ++i) res *= 10;
        return res;
    };

    for (int D = M; D < L_N; ++D) {
        for (int p = 0; p <= D - M; ++p) {
            if (p == 0) {
                if (S[0] == '0') continue;
                total += p10(D - M);
            } else {
                long long pref_choices = 9 * p10(p - 1);
                long long suf_choices = p10(D - M - p);
                total += pref_choices * suf_choices;
            }
        }
    }

    int D = L_N;
    for (int p = 0; p <= D - M; ++p) {
        int suf_len = D - M - p;
        long long suf_pow = p10(suf_len);

        if (p == 0) {
            if (S[0] == '0') continue;
            string N_mid = N_str.substr(p, M);
            if (S < N_mid) {
                total += suf_pow;
            } else if (S == N_mid) {
                if (suf_len == 0) {
                    total += 1;
                } else {
                    long long N_suf = stoll(N_str.substr(p + M, suf_len));
                    total += N_suf + 1;
                }
            }
        } else {
            long long N_pref = stoll(N_str.substr(0, p));
            long long min_pref = p10(p - 1);

            if (N_pref > min_pref) {
                long long num_smaller = N_pref - min_pref;
                total += num_smaller * suf_pow;
            }

            string N_mid = N_str.substr(p, M);
            if (S < N_mid) {
                total += suf_pow;
            } else if (S == N_mid) {
                if (suf_len == 0) {
                    total += 1;
                } else {
                    long long N_suf = stoll(N_str.substr(p + M, suf_len));
                    total += N_suf + 1;
                }
            }
        }
    }

    return total;
}

void solve() {
    string S;
    long long L, R;
    if (!(cin >> S >> L >> R)) return;
    long long ans = count_occurrences(R, S) - count_occurrences(L - 1, S);
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (cin >> T) {
        while (T--) solve();
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    vector<long long> H(N);
    for (int i = 0; i < N; ++i) cin >> H[i];

    vector<int> dp = {1};

    for (int i = 0; i < N - 1; ++i) {
        int n = i + 2;
        int old_sz = dp.size();
        vector<int> pref(old_sz + 1, 0);
        for (int k = 0; k < old_sz; ++k) {
            pref[k + 1] = (pref[k] + dp[k]) % MOD;
        }

        vector<int> nxt(n, 0);
        long long h_prev = H[i];
        long long h_cur = H[i + 1];

        for (int j = 0; j < n; ++j) {
            if (h_prev < h_cur) {
                if (j < old_sz) {
                    int val = (pref[old_sz] - pref[j]) % MOD;
                    if (val < 0) val += MOD;
                    nxt[j] = val;
                } else {
                    nxt[j] = 0;
                }
            } else if (h_prev > h_cur) {
                int lim = min(j, old_sz);
                nxt[j] = pref[lim];
            } else {
                nxt[j] = pref[old_sz];
            }
        }
        dp = move(nxt);
    }

    int ans = 0;
    for (int x : dp) ans = (ans + x) % MOD;
    cout << ans << "\n";
    return 0;
}

