int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N)) return 0;
    adj.assign(N + 1, vector<int>());
    vector<pair<int, int>> edges;
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        edges.push_back({u, v});
    }

    int best_color = 1e9;
    long long best_leaves = -1;

    auto update = [&](int col, long long lvs) {
        if (col < best_color) {
            best_color = col;
            best_leaves = lvs;
        } else if (col == best_color) {
            if (best_leaves == -1 || lvs < best_leaves) {
                best_leaves = lvs;
            }
        }
    };

    // Option 1: Vertex center
    for (int r = 1; r <= N; ++r) {
        vector<int> dist(N + 1, -1);
        vector<int> parent(N + 1, 0);
        queue<int> q;
        q.push(r);
        dist[r] = 0;
        int max_d = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            max_d = max(max_d, dist[u]);
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.push(v);
                }
            }
        }

        int col = max_d + 1;
        vector<int> max_c(max_d, 0);
        for (int u = 1; u <= N; ++u) {
            int d = dist[u];
            if (d < max_d) {
                int ch = 0;
                for (int v : adj[u]) {
                    if (parent[v] == u) ch++;
                }
                max_c[d] = max(max_c[d], ch);
            }
        }

        long long leaves = 1;
        for (int d = 0; d < max_d; ++d) {
            leaves *= max(1, max_c[d]);
        }
        update(col, leaves);
    }

    // Option 2: Edge center
    for (auto edge : edges) {
        int u = edge.first;
        int v = edge.second;

        vector<int> dist(N + 1, -1);
        vector<int> parent(N + 1, 0);
        queue<int> q;
        q.push(u);
        dist[u] = 0;
        parent[u] = -1;

        q.push(v);
        dist[v] = 0;
        parent[v] = -1;

        int max_d = 0;
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            max_d = max(max_d, dist[curr]);
            for (int nxt : adj[curr]) {
                if ((curr == u && nxt == v) || (curr == v && nxt == u)) continue;
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    parent[nxt] = curr;
                    q.push(nxt);
                }
            }
        }

        int col = max_d + 1;
        vector<int> max_c(max_d, 0);
        for (int node = 1; node <= N; ++node) {
            int d = dist[node];
            if (d < max_d) {
                int ch = 0;
                for (int nxt : adj[node]) {
                    if (parent[nxt] == node) ch++;
                }
                max_c[d] = max(max_c[d], ch);
            }
        }

        long long leaves = 2;
        for (int d = 0; d < max_d; ++d) {
            leaves *= max(1, max_c[d]);
        }
        update(col, leaves);
    }

    cout << best_color << " " << best_leaves << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

struct Fenwick {
    int n;
    vector<int> tree;
    Fenwick(int n) : n(n), tree(n + 2, 0) {}

    void add(int i, int delta) {
        for (; i <= n; i += i & -i) tree[i] += delta;
    }

    int query(int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<vector<pair<int, int>>> by_len(M + 2);
    for (int i = 0; i < N; ++i) {
        int l, r;
        cin >> l >> r;
        int len = r - l + 1;
        if (len <= M) {
            by_len[len].push_back({l, r});
        }
    }

    Fenwick bit(M + 1);
    int long_count = N;

    for (int d = 1; d <= M; ++d) {
        for (auto& seg : by_len[d - 1]) {
            long_count--;
            bit.add(seg.first, 1);
            bit.add(seg.second + 1, -1);
        }

        int ans = long_count;
        for (int k = d; k <= M; k += d) {
            ans += bit.query(k);
        }
        cout << ans << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

struct Edge {
    int u, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A;
    if (!(cin >> N >> A)) return 0;
    vector<Edge> type1(A);
    for (int i = 0; i < A; ++i) {
        cin >> type1[i].u >> type1[i].v;
    }

    int B;
    cin >> B;
    vector<Edge> type2(B);
    for (int i = 0; i < B; ++i) {
        cin >> type2[i].u >> type2[i].v;
    }

    int ans = 0;

    for (int mask = 0; mask < (1 << B); ++mask) {
        vector<vector<int>> adj(N + 1);
        vector<int> in_degree(N + 1, 0);
        vector<bool> forbidden(N + 1, false);

        for (const auto& e : type1) {
            adj[e.v].push_back(e.u);
        }

        for (int i = 0; i < B; ++i) {
            if (mask & (1 << i)) {
                adj[type2[i].u].push_back(type2[i].v);
            } else {
                forbidden[type2[i].u] = true;
            }
        }

        queue<int> q;
        for (int i = 1; i <= N; ++i) {
            if (forbidden[i]) q.push(i);
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (!forbidden[v]) {
                    forbidden[v] = true;
                    q.push(v);
                }
            }
        }

        vector<int> deg(N + 1, 0);
        for (int u = 1; u <= N; ++u) {
            if (forbidden[u]) continue;
            for (int v : adj[u]) {
                if (!forbidden[v]) {
                    deg[v]++;
                }
            }
        }

        queue<int> topo_q;
        int painted = 0;
        for (int i = 1; i <= N; ++i) {
            if (!forbidden[i] && deg[i] == 0) {
                topo_q.push(i);
            }
        }

        while (!topo_q.empty()) {
            int u = topo_q.front();
            topo_q.pop();
            painted++;
            for (int v : adj[u]) {
                if (!forbidden[v]) {
                    deg[v]--;
                    if (deg[v] == 0) {
                        topo_q.push(v);
                    }
                }
            }
        }

        ans = max(ans, painted);
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

const long long INF = 1e16;

long long solve_1d(int L, const map<int, vector<int>>& events_by_t) {
    vector<long long> dp(L + 1, 0);

    for (const auto& kv : events_by_t) {
        vector<int> pts = kv.second;
        sort(pts.begin(), pts.end());

        vector<pair<int, int>> intervals;
        int cur_l = pts[0], cur_r = pts[0];
        for (size_t i = 1; i < pts.size(); ++i) {
            if (pts[i] == cur_r + 1) {
                cur_r = pts[i];
            } else {
                intervals.push_back({cur_l, cur_r});
                cur_l = cur_r = pts[i];
            }
        }
        intervals.push_back({cur_l, cur_r});

        vector<pair<int, long long>> updates;

        for (auto& iv : intervals) {
            int l = iv.first;
            int r = iv.second;

            long long m1 = INF;
            long long m2 = INF;
            for (int x = l; x <= r; ++x) {
                if (dp[x] < INF) {
                    m1 = min(m1, dp[x] + x);
                    m2 = min(m2, dp[x] - x);
                }
                dp[x] = INF;
            }

            if (l > 1 && m1 < INF) {
                updates.push_back({l - 1, m1 - l + 1});
            }
            if (r < L && m2 < INF) {
                updates.push_back({r + 1, m2 + r + 1});
            }
        }

        for (auto& up : updates) {
            dp[up.first] = min(dp[up.first], up.second);
        }
    }

    long long min_cost = INF;
    for (int x = 1; x <= L; ++x) {
        min_cost = min(min_cost, dp[x]);
    }
    return min_cost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H, Q;
    if (!(cin >> W >> H >> Q)) return 0;

    map<int, vector<int>> beams_x, beams_y;
    for (int i = 0; i < Q; ++i) {
        int t, d, x;
        cin >> t >> d >> x;
        if (d == 0) {
            beams_x[t].push_back(x);
        } else {
            beams_y[t].push_back(x);
        }
    }

    long long cost_x = solve_1d(W, beams_x);
    long long cost_y = solve_1d(H, beams_y);

    if (cost_x >= INF || cost_y >= INF) {
        cout << -1 << "\n";
    } else {
        cout << cost_x + cost_y << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int B, W;
    if (!(cin >> B >> W)) return 0;

    int N = B + W;

    vector<long long> fact(N + 1, 1), invFact(N + 1, 1);
    for (int i = 1; i <= N; ++i) fact[i] = (fact[i - 1] * i) % MOD;
    invFact[N] = modInverse(fact[N]);
    for (int i = N - 1; i >= 0; --i) invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;

    auto nCr = [&](int n, int r) -> long long {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    };

    vector<long long> pow_half(N + 1, 1);
    long long half = modInverse(2);
    for (int i = 1; i <= N; ++i) pow_half[i] = (pow_half[i - 1] * half) % MOD;

    long long S_W = 0, S_B = 0;

    for (int i = 1; i <= N; ++i) {
        int n = i - 1;
        if (n >= 1) {
            if (n - 1 >= W - 1) {
                long long term = nCr(n - 1, W - 1) * pow_half[n] % MOD;
                S_W = (S_W + term) % MOD;
            }
            if (n - 1 >= B - 1) {
                long long term = nCr(n - 1, B - 1) * pow_half[n] % MOD;
                S_B = (S_B + term) % MOD;
            }
        }

        long long diff = (S_W - S_B) % MOD;
        if (diff < 0) diff += MOD;

        long long ans = (half + half * diff) % MOD;
        cout << ans << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

const int OFFSET = 4005;
const int MAX_SPAN = 8010;

bool ok_ab[MAX_SPAN];
bool ok_ac[MAX_SPAN];
bool ok_bc[MAX_SPAN];

void compute_match(const string& x, const string& y, bool ok[]) {
    int lx = x.size(), ly = y.size();
    for (int offset = -4000; offset <= 4000; ++offset) {
        bool match = true;
        for (int i = 0; i < ly; ++i) {
            int pos_x = offset + i;
            if (pos_x >= 0 && pos_x < lx) {
                if (x[pos_x] != '?' && y[i] != '?' && x[pos_x] != y[i]) {
                    match = false;
                    break;
                }
            }
        }
        ok[offset + OFFSET] = match;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    int la = a.size(), lb = b.size(), lc = c.size();

    compute_match(a, b, ok_ab);
    compute_match(a, c, ok_ac);
    compute_match(b, c, ok_bc);

    int ans = la + lb + lc;

    for (int i = -2000; i <= 2000; ++i) {
        if (!ok_ab[i + OFFSET]) continue;
        for (int j = -2000; j <= 2000; ++j) {
            if (!ok_ac[j + OFFSET]) continue;
            if (!ok_bc[j - i + OFFSET]) continue;

            int left = min(0, min(i, j));
            int right = max(la, max(i + lb, j + lc));
            ans = min(ans, right - left);
        }
    }

    cout << ans << "\n";
    return 0;
}
